\caption{An implementation of a greedy $2\Delta-1$ online edge-coloring algorithm using $O(n \Delta)$ bits of space \label{alg:simple-greedy}}
\begin{algorithmic}[1]
\Statex \textbf{Input}: Stream of edges in an $n$-vertex graph $G = (V,E)$
  \Statex
  \Statex \underline{\textbf{Initialize}:}
  \For{$v \in V$}
  \State $U_v \gets \emptyset$ is a subset of $[2\Delta-1]$
  \EndFor
  \Statex

\Statex \underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ color} 
  \State Let $c$ be arbitrary color in $[2\Delta-1] \setminus U_x \setminus U_y$
  \State Add $c$ to $U_x$ and to $U_y$
  \State \textbf{return} color $c$
\end{algorithmic}

We claim \Cref{alg:gen-to-bpt} works for sufficiently large $n$.

\begin{algorithm}[htb!]
  \caption{Algorithm to partition general graph edges into bipartite graphs\label{alg:gen-to-bpt}}
  \begin{algorithmic}[1]
  \Statex \textbf{Input}: Stream of edges in an $n$-vertex graph $G=(V,E)$
    \Statex
    \Statex \underline{\textbf{Initialize}:}
    \For{$v \in V$}
      \State $\deg_{F_i}(v) \gets 0$
    \EndFor
    \State Setup binary code $\mathcal{C}$ of length $t := 4 \ceil{\log n}$ from \Cref{cor:practical-binary-codes}
    \For{$i \in [t]$}
      \State Let $F_i$ be the bipartition with parts $A_i = \{v \in V : \mathcal{C}(v)_i = 0 \}$ and $B_i = \{v \in V : \mathcal{C}(v)_i = 1 \}$
    \EndFor

  \Statex 
  \Statex\underline{\textbf{Process}(edge $\{x,y\}$)}
    \State Let $\deg(x) = \sum_{i \in [t]} \deg_{F_i}(x)$ and $\deg(y) = \sum_{i \in [t]} \deg_{F_i}(y)$.
    \For{$i \in [t]$}
        \If{$\mathcal{C}(x)_i \ne \mathcal{C}(y)_i$ and $\deg_{F_i}(x) \le 1200 \deg(x) / t$ and $\deg_{F_i}(y) \le 1200 \deg(y) / t$}\label{line:gen-to-bpt-edge-cond}
            \State Increase $\deg_{F_i}(x)$ and $\deg_{F_i}(y)$ by 1
            \State Assign edge $\{x,y\}$ to $F_i$
            \State \textbf{return}
        \EndIf
    \EndFor
    \State unreachable \label{line:gen-to-bpt-unreachable}
  \end{algorithmic}
\end{algorithm}

It is clear that at each point in time, for all $v \in V$ and $i \in [t]$, the algorithm will have $\deg_{F_i}(v)$ be the number of edges assigned to $F_i$ incident on $v$.

Line \ref{line:gen-to-bpt-edge-cond} of the algorithm ensures that before
edge $\{x,y\}$ is assigned, $\deg_{F_i}(x) \le 1200 \deg(x) / t$. Consequently, after the edge is assigned, $\deg_{F_i}(x) \le 1200 \deg(x) / t + 1 \le 300 \deg(x) / \log(n) + 1$. Similarly, we will have $\deg_{F_i}(y) \le 300 \deg(y) / \log(n) + 1$.

It remains to prove that the algorithm will always assign an edge, and that Line \ref{line:gen-to-bpt-unreachable} is never reached. When processing edge an $\{x,y\}$,
define $B_v := \{i \in [t]: \deg_{F_i}(v) > 1200 \deg(v) / t$. By Markov's inequality,
since $\sum_{i\in[t]} \deg_{F_i}(v) = \deg(v)$, $|B_v| \le t / 1200$. Because the code
$\mathcal{C}$ has minimum distance $t / 400$, the set $K = \{i : \mathcal{C}(x)_i \ne \mathcal{C}(y)_i\}$ has size $\ge t/400$; and the set of $i \in [t]$ for which Line \ref{line:gen-to-bpt-edge-cond} passes has size $|K \setminus B_x \setminus B_y| \ge t/400 - t/1200 - t/1200 = t/1200$,
and hence is nonempty.

