\begin{algorithm}[htb!]
  \caption{Randomized algorithm for $5 \Delta$ edge coloring for (adversarial) one sided vertex arrival bipartite streams\label{alg:bpt-rand-va-edgecol}}
  \begin{algorithmic}[1]
  \Statex \textbf{Input}: Stream of vertex arrivals $n$-vertex graph $G=(A \sqcup B,E)$
    \Statex
    \Statex \underline{\textbf{Initialize}:}
    \State Let $C = 5 \Delta$.
    \For{$v \in B$}
      \State Let $\sigma_v$ be a uniformly random permutation over $[C]$ \Comment{constructed on demand from random oracle bits}.
      \State $h_v \gets 1$.

    \EndFor

  \Statex \underline{\textbf{Process}(vertex $x$ with multiset $M_v$ of edges to $B$)}
    \State Let $S \gets \emptyset$ \Comment{Set of colors $M_x$ will have used so far}
    \For{$e = \{x,y\}$ in $M_x$, in arbitrary order}
      \While{$h_y \le C \land \sigma_y[h_y] \in S$}\label{step:bpt-rand-va-edgecol-pick-loop}
        \State $h_y \gets h_y + 1$
      \EndWhile
      \If{$h_y > C$}\State abort \EndIf
      \State Assign color $\sigma_y[h_y]$ to $e$\label{step:bpt-rand-va-edgecol-color-assigned}
      \State $S \gets S \cup \{\sigma_y[h_y] \}$
      \State $h_y \gets h_y + 1$ \label{step:bpt-rand-va-edgecol-step-hy}
    \EndFor
  \end{algorithmic}
\end{algorithm}

This algorithm will never assign the same color to any pair of edges adjacent to
the same vertex; at worst, it will abort. The condition on
Line \ref{step:bpt-rand-va-edgecol-pick-loop} ensures
that when a vertex $x$ is processed, no two edges will be assigned the same color.
On the other hand, after Line \ref{step:bpt-rand-va-edgecol-color-assigned} assigns
a color to an edge, Line \ref{step:bpt-rand-va-edgecol-step-hy} increases $h_y$;
because $\sigma_v$ is a permutation, this prevents the algorithm from ever
assigning the same color twice to edges incident on some vertex $y$ in $B$.

For the rest of the proof, we will argue that the algorithm never aborts; equivalently,
that $h_y \le C$ always holds for all $y \in B$. In fact, we shall prove the stronger
claim, that $h_y \le C - 2 \Delta$ holds with probability $\ge 1 - \delta / n$
for each individual $y \in B$. Consider a specific vertex $y \in B$.
For each $i \in [\Delta]$, let $V_{y,i}$
be the random variable counting the number of times that the loop starting at
Line \ref{step:bpt-rand-va-edgecol-pick-loop} ran, when the $i$th edge adjacent
to $y$ was processed. If there was no $i$th edge (or the algorithm already aborted), 
we set $V_{y,i} = 0$; then at the end of the stream, we will have
$h_y \le \Delta + \sum_{i\in\Delta} V_{y,i}$.

We now consider the distribution of $V_{y,i}$, conditioned on both the value of the
variable $S$ at the time the $i$th edge was processed, and on the parts of
the permutation $\sigma_y$ which the algorithm has read so far, $\sigma_y[1..{h_y-1}]$.
\begin{align*}

  \Pr[V_{y,i} \ge k \mid S, \sigma_y[1..{h_y-1}]] &= \Pr[\sigma_y[h_y,\ldots,h_y + k - 1] \subseteq S \mid S, \sigma_y[1..{h_y-1}]] \\
    &= \binom{|S \cap \sigma_y[h_y,...,C]|}{k} / \binom{C - h_y - 1}{k}  \\
    & \le \binom{\Delta}{k} / \binom{2 \Delta}{k} \qquad\qquad \text{since $|S|\le\Delta$, $h_y \le C - 2\Delta$} \\
    &\le \frac{\Delta\cdot (\Delta-1) \cdots (\Delta -k +1)}{2\Delta \cdot (2\Delta-1) \cdots (2\Delta -k +1)} \le \frac{1}{2^k}
\end{align*}

Since this bound holds for all values of $S$ and all $\sigma_y[1..{h_y-1}]$, in particular we
have
\begin{align*}
  \Pr[V_{y,i} \ge k | (V_{y,j})_{j < i}] = \mathbb{E}_{\text{$S,\sigma_y[1..{h_y-1}]$ compat with $(V_{y,j})_{j < i}$}} \Pr[V_{y,i} \ge k |S,\sigma_y[1..{h_y-1}]] \le \frac{1}{2^k}
\end{align*}
By \Cref{lem:moment-gen-func}, for $e^t \in [1,2)$, we have $\mathbb{E}[e^{t V_{y,i} } \mid (V_{y,j})_{j < i}] \le 1 / (2 - e^t)$, and $\mathbb{E}[V_{y,i} \mid (V_{y,j})_{j < i}] \le 1$.

By a slight variation on the Chernoff bound:
\begin{align*}
  \Pr[\sum_{i=1}^{\Delta} V_{y,i} \ge 2 \Delta] &\le \inf_{t\ge 0} \Pr\left[\prod_{i=1}^{\Delta} e^{t V_{y,i}} \ge e^{2 t \Delta}\right] \\
   &\le \inf_{t\ge 0} \frac{1}{e^{2 t \Delta}} \mathbb{E}[e^{t V_{y,1}} \cdots \mathbb{E}\left[e^{t V_{y,\Delta}} \mid (V_{y,j})_{j<\Delta}\right] \cdots ]  \\
   &\le \min_{t : e^t \in [1,2)} \frac{1}{e^{2 t \Delta}} \left(\frac{1}{2 - e^t}\right)^\Delta = \left( \min_{t : e^t \in [1,2)} \frac{1}{e^{2t} (2-e^t)}\right)^\Delta \\
   &= \left( \frac{1}{\max_{x \in [1,2)} x^2 (2-x)}\right)^\Delta = \left(\frac{27}{32}\right)^\Delta \le \exp(-\Delta/6)
\end{align*}
Since $h_v \le \Delta + \sum_{i\in\Delta} V_{y,i}$, this implies that
\begin{align*}
  \Pr[h_v \ge C] \le \Pr[h_v \ge C - 2 \Delta] = \Pr[h_v \ge 3 \Delta] \le \Pr[\sum_{i=1}^{\Delta} V_{y,i} \ge 2 \Delta] \le  \exp(-\Delta/6)
\end{align*}
Thus, by a union bound, the probability that \emph{any} vertices $v \in B$ will have $h_v > C$ at the end of the algorithm will be $\le n \exp(-\Delta/6)$. In particular, if $\Delta \ge 6 \ln(n / \delta)$, the algorithm will the guaranteed to abort with probability $\le \delta$.

