\label{lem:approx-indep-large-anticoncentration}
  Let $C,t,w$ be integers, with $C \ge t \ge 512$, and $8 | C$. Let $\epsilon \le C^{-t - 1}$. Say that $F_1,\ldots,F_w$ are subsets of $[C]$, and define $s_i = |F_i|$ for all $i \in [w]$. We furthermore require $\min_{i \in [w]} s_i \ge \frac{1}{2} t$, and $\min_{i \in [w]} s_i \ge \frac{1}{2} \max_{i\in[w]} s_i$. Let $X \subseteq [C]$ satisfy $|X| \le \frac{1}{8} C$, and let $\sum_{i \in [w]} s_i \le \frac{1}{2} C$. Then if $\sigma_1,\ldots,\sigma_w$ are $(\epsilon,t)$-wise independent random permutations over $[C]$,
  \begin{align*}
    \Pr\left[\left| \bigcup_{i \in [w]} \sigma_i[F_i] \setminus X \right| < \frac{1}{8} \sum_{i \in [w]} s_i \right] \le \exp(- \frac{1}{2^9} t w) \,.
  \end{align*}

\begin{align*}
    \Pr\left[\left| \bigcup_{i \in [w]} \sigma_i[F_i] \setminus X \right| < \frac{1}{8} \sum_{i \in [w]} s_i \right] \le \exp(- \frac{1}{2^9} t w) \,.
  \end{align*}

Since the $(\sigma_i)_{i\in [w]}$ are $(\epsilon,t)$-wise independent, in particular we have for any $i\in [w]$,$j \in [C]$, that $\Pr\left[j \in \sigma_i[F_i]\right] \le s_i / C + \epsilon$, and for any $Q \subseteq [C]$ with $|Q| \le t$, that 
\begin{align}
  \Pr[Q \subseteq \sigma_i[F_i]] = \frac{s_i \cdot (s_i-1) \cdots (s_i - |Q| + 1)}{C \cdot (C-1) \cdots (C - |Q|+1)} + \epsilon \le \left(\frac{s_i}{C}\right)^{|Q|}  \label{eq:apx-comb-bound}
\end{align}
Let $U_i$ be a random subset of $[C]$ in which each element in $C$ is included independently with probability $s_i / C$. Eq. \ref{eq:apx-comb-bound} thus implies $\Pr[Q \subseteq \sigma_i[F_i]] \le \Pr[Q \subseteq U_i]$. Now, for any fixed set $H \subseteq [C]$, let $Y_{H,i} := |\sigma_i[F_i] \cap H|$, and $W_{H,i} = |U_i \cap H|$.  Then $\mathbb{E}[Y_{H,i}] \le s_i |H| / C + \epsilon C = \mathbb{E}[W_{H,i}] + \epsilon C$, and as a consequence of Eq. \ref{eq:apx-comb-bound}, we have for all $k \le t$, that $\mathbb{E}[Y_{H,i}^k] \le \mathbb{E}[W_{H,i}^k] + \epsilon C$. This lets us bound the moment generating function of $Y_{H,i}$, for nonnegative $z$:
\begin{align}
  \mathbb{E} e^{z Y_{H,i}} &\le \sum_{k = 0}^{\infty} \frac{1}{k!} (\mathbb{E} (z Y_{H,i})^k) \nonumber\\
    &\le \sum_{k=0}^{t} \frac{1}{k!} (\mathbb{E} (z Y_{H,i})^k) + \sum_{k=t+1}^{\infty} \frac{1}{k!} (\mathbb{E} (z Y_{H,i})^k) \nonumber\\
    &\le \sum_{k = 0}^{t} \frac{1}{k!} (\mathbb{E} (z W_{H,i})^k) + \sum_{k=t+1}^{\infty} \frac{1}{(k-t-1)!(t+1)!} ((z s_i)^{k}) + \epsilon t C \nonumber\\
    &\le \mathbb{E} e^{z W_{H,i}} + \frac{(z s_i)^{t+1}}{(t+1)!} e^{z s_i}  + \epsilon t C \nonumber\\
    &\le \exp\left({\frac{s_i |H|}{C} (e^z - 1)} \right) +\frac{(z s_i)^{t+1}}{(t+1)!} e^{z s_i} +  \epsilon t C \label{eq:moment-bound}
\end{align}

We will use this to upper bound the probability that a supermartingale, which sums
how many elements in each $\sigma_i[F_i]$ were present in $\bigcup_{j < i} \sigma_j[F_j]$, grows too large. Let $B_1$ be an arbitrary set of size $\frac{1}{8} C$ which contains $X$. (This definition will make the following analysis simpler than if we had set $B_1 = X$). For each $i \in \{2,\ldots, w\}$, define $B_i = B_{i-1} \cup \sigma_{i-1}[F_{i-1}]$. Note that $|B_w| \le \frac{5}{8} C$. We have $\mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}] \le \sum_{i \in [w]}{\left(\frac{|B_i|}{C} s_i + \epsilon C\right)} \le \frac{|B_w|}{C} \sum_{i \in [w]} s_i \le \frac{5}{8} \sum_{i \in [w]} s_i$.

Note that
\begin{align}
  \Pr\left[\left| \bigcup_{i \in [w]} \sigma_i[F_i] \setminus X \right|  < \frac{1}{8} \sum_{i \in [w]} s_i \right] & \le \Pr\left[\sum_{i \in [w]} Y_{B_i,i} \ge \frac{7}{8} \sum_{i\in[w]} s_i \right] \label{eq:ybi-excess}
\end{align}
Let $\gamma = (\frac{7}{8} \sum_{i\in[w]} s_i) / \mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}] $; this is $\ge 7/5$. Applying a modified proof of the Chernoff bound/Azuma's inequality to the right hand side of Eq. \ref{eq:ybi-excess} gives:
\begin{align*}
  &= \inf_{z > 0} \Pr\left[\exp\left(z \sum_{i \in [w]} Y_{B_i,i}\right) \ge \exp\left(\gamma z \mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}]\right) \right] \\
  &\le  \inf_{z > 0} \frac{\exp\left(z \sum_{i \in [w]} Y_{B_i,i}\right) }{\exp\left(\gamma z \mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}]\right)} \qquad\qquad \text{by Markov's inequality} \\ 
  &= \inf_{z > 0} \exp\left(z \sum_{i \in [w]} (Y_{B_i,i} - \gamma \mathbb{E}[Y_{B_i,i} ])\right) \\
  &= \inf_{z > 0} \mathbb{E}\left[\exp\left(z (Y_{B_1,1} - \gamma \mathbb{E}[Y_{B_1,1}])\right) \cdots \mathbb{E}\left[\exp\left(z (Y_{B_w,w} - \gamma \mathbb{E}[Y_{B_w,w}])\right) \big\vert Y_{B_1,1}, \ldots, Y_{B_{w-1},w-1}\right] \cdots  \right] \\
  &\le \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \mathbb{E} \exp\left(z (Y_{B,i} - \gamma \mathbb{E}[Y_{B,i}])\right) \qquad\qquad \text{bounding terms from the inside out} \\
  &= \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\mathbb{E} \exp\left(z Y_{B,i}\right)}{\exp\left(\gamma z\mathbb{E}[Y_{B,i}])\right) } \\
  &\le \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\exp\left({\frac{s_i |B|}{C} (e^z - 1)} \right) +\frac{(z s_i)^{t+1}}{(t+1)!} e^{z s_i} +  \epsilon t C}{\exp\left(\gamma z\mathbb{E}[Y_{B,i}])\right) } \qquad\qquad \text{by Eq. \ref{eq:moment-bound} }
\end{align*}
Now set $z = \frac{t}{8 \frac{1}{w} \sum_{i\in[w]} s_i}$. Since $t \le 2 \min_{i \in [w]} s_i$, it follows $z \le \frac{2 \min_{i \in [w]} s_i}{8 \min_{i \in [w]} s_i} \le \frac{1}{4}$. Since $\max_{i \in [w]} s_i \le 2 \min_{i \in [w]} s_i$, we have $z \le t / (4 s_i)$ for all $i \in [w]$. This implies $(zs_i)^{t+1}/(t+1)! e^{z s_i} \le {(t/4)}^{t+1} e^{t/4} / (t+1)! \le \frac{1}{2}$.
Since $\epsilon \le C^{-t-1}$, we also have $\epsilon t C \le \frac{1}{2}$. Continuing the upper bound of Eq. \ref{eq:ybi-excess}:
\begin{align*}
  &\le \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\exp\left({\frac{s_i |B|}{C} (e^z - 1)} \right) + 1}{\exp\left(\gamma ((z s_i |B| / C) - \epsilon) \right) } \hspace{-2cm} \\
  &\le e^{\gamma w \epsilon} \prod_{i \in [w]} \frac{\exp\left({\frac{s_i}{8} (e^z - 1)} \right) + 1}{\exp\left(\gamma z s_i / 8 \right) }  &\text{maximum occurs at $|B| = \frac{1}{8} C$}\\
  &\le e^{w (\ln(2) + \gamma \epsilon)} \prod_{i \in [w]} \exp( (e^z - 1 - \gamma z) s_i / 8 )  &\text{since $(x+1)/x^\gamma \le 2/x^{\gamma -1}$} \\
  &\le e^{w (\ln(2) + \gamma \epsilon)} \prod_{i \in [w]} \exp\left( -\frac{1}{4} z \frac{s_i}{8} \right)  &\hspace{-4cm}\text{since $z \le \frac{1}{4}$ implies $\frac{1}{4} z \le \frac{7}{5} z - (e^z-1)$} \\
  & = \exp\left( - \frac{1}{4} \frac{t w}{8 \sum_{i \in [w]} s_i} \sum_{i \in [w]} \frac{s_i}{8}  + w (\ln 2 + \gamma \epsilon)\right) \hspace{-2cm} \\
  &\le \exp( - \frac{t w}{2^8}  + w (\ln 2 + \gamma \epsilon)) \\
  &\le \exp( - \frac{t w}{2^9})  &\text{since $\frac{t}{2^9} \ge 1 \ge \ln 2 + \gamma \epsilon$}
\end{align*}
This completes the proof of the lemma.

