    &\le \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\exp\left({\frac{s_i |B|}{C} (e^z - 1)} \right) +\frac{(z s_i)^{t+1}}{(t+1)!} e^{z s_i} +  \epsilon t C}{\exp\left(\gamma z\mathbb{E}[Y_{B,i}])\right) } \qquad\qquad \text{by Eq. \ref{eq:moment-bound} }
  \end{align*}

\begin{align*}
    &\le \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\exp\left({\frac{s_i |B|}{C} (e^z - 1)} \right) + 1}{\exp\left(\gamma ((z s_i |B| / C) - \epsilon) \right) } \hspace{-2cm} \\
    &\le e^{\gamma w \epsilon} \prod_{i \in [w]} \frac{\exp\left({\frac{s_i}{8} (e^z - 1)} \right) + 1}{\exp\left(\gamma z s_i / 8 \right) }  &\text{maximum occurs at $|B| = \frac{1}{8} C$}\\
    &\le e^{w (\ln(2) + \gamma \epsilon)} \prod_{i \in [w]} \exp( (e^z - 1 - \gamma z) s_i / 8 )  &\text{since $(x+1)/x^\gamma \le 2/x^{\gamma -1}$} \\
    &\le e^{w (\ln(2) + \gamma \epsilon)} \prod_{i \in [w]} \exp\left( -\frac{1}{4} z \frac{s_i}{8} \right)  &\hspace{-4cm}\text{since $z \le \frac{1}{4}$ implies $\frac{1}{4} z \le \frac{7}{5} z - (e^z-1)$} \\
    & = \exp\left( - \frac{1}{4} \frac{t w}{8 \sum_{i \in [w]} s_i} \sum_{i \in [w]} \frac{s_i}{8}  + w (\ln 2 + \gamma \epsilon)\right) \hspace{-2cm} \\
    &\le \exp( - \frac{t w}{2^8}  + w (\ln 2 + \gamma \epsilon)) \\
    &\le \exp( - \frac{t w}{2^9})  &\text{since $\frac{t}{2^9} \ge 1 \ge \ln 2 + \gamma \epsilon$}
  \end{align*}

\label{lem:approx-indep-small-anticoncentration}
  Let $C,s,w$ be integers, with $s \ge 4$. Let $\epsilon \le C^{-s - 1}$. Say that $F_1,\ldots,F_w$ are subsets of $[C]$, with each $|F_i| \le s$, $|F_i| \ge 2$ and $\sum_{i \in [w]} |F_i| \ge \frac{1}{2} C$. Furthermore, let $X \subseteq [C]$ satisfy $|X| \le \frac{1}{8} C$. Then if $\sigma_1,\ldots,\sigma_w$ are $(\epsilon,s)$-wise independent random permutations over $[C]$,
  \begin{align*}
    \Pr\left[\left| \bigcup_{i \in [w]} \sigma_i[F_i] \setminus X \right| < \frac{1}{16} C \right] \le \exp(- \frac{1}{2} \sum_{i \in[w]} |F_i|) \,.
  \end{align*}

  This lemma differs from \Cref{lem:approx-indep-large-anticoncentration} in that the sets $(\sigma_i[F_i])_{i \in [w]}$ are now smaller, and $\sum_{i\in[w]} |F_i|$ is $\Omega(C)$.

\begin{align*}
    \Pr\left[\left| \bigcup_{i \in [w]} \sigma_i[F_i] \setminus X \right| < \frac{1}{16} C \right] \le \exp(- \frac{1}{2} \sum_{i \in[w]} |F_i|) \,.
  \end{align*}

$\delta \in (0,1)$ is a parameter governing the probability that the  \Cref{alg:bpt-det-va-edgecol} will fail to be a correct deterministic algorithm, if its advice is chosen randomly; if one just wants a deterministic algorithm, setting $\delta = 1/2$ suffices. If $\Delta \le \log\frac{n \Delta}{\delta}$, use the simple greedy algorithm (\Cref{alg:simple-greedy}). Otherwise, use \Cref{alg:bpt-det-va-edgecol}.

\begin{algorithm}[htb!]
  \caption{Deterministic algorithm for $O(\Delta)$ edge coloring for (adversarial) one sided vertex arrival bipartite streams, using $\widetilde{O}(n)$ bits of advice\label{alg:bpt-det-va-edgecol}}
  \begin{algorithmic}[1]
  \Statex \textbf{Input}: Stream of vertex arrivals for $n$-vertex graph $G=(A \sqcup B,E)$ of max degree $\Delta$
    \Statex
    \Statex $\delta \in (0,1)$ is a parameter so that, if the advice is chosen randomly, it will work for all inputs with probability $\ge 1 - \delta$
    \Statex
    \Statex \underline{\textbf{Initialize}:}
    \Statex Let $C = 2^{18} \Delta$. 
    \Statex Let $s = \ceil{2^{18} \log\frac{n \Delta}{\delta}} $.
    \Statex Advice: $(\sigma_v)_{v \in B}$, where each $\sigma_v$ is a permutation over $[C]$. If chosen randomly, each is $(\epsilon,s)$-wise independent for $\epsilon \le C^{-s - 1}$

    \For{$v \in B$}
      \State $b_v \gets 1$.
      \State $Q_v \gets [s]$.
    \EndFor

  \Statex \underline{\textbf{Process}(vertex $x$ with multiset $M_x$ of edges to $B$)}
    \Statex Let $d_{x,y}$ be the number of times edge $\{x,y\}$ is in $M_x$
    \For{each $y \in B$ with $d_{x,y} > 0$}
      \If{$d_{x,y} < \frac{1}{16} s$}
        \State Let $F_y = (b_y -1) s + Q_y$\label{step:bpt-det-va-edgecol-low-deg-fy}
      \Else
        \State Let $F_y = ((b_y -1) s + Q_y) \sqcup [b_y s, b_y + \ceil{\frac{64 d_{a,b}}{s}} s]$\label{step:bpt-det-va-edgecol-high-deg-fy}
      \EndIf
    \EndFor
    \State Construct bipartite graph $H$ from $M_x$ to $[C]$, edge $e \in M_x$
    is linked to all $c \in \sigma_y[F_y]$.\label{step:bpt-det-va-edgecol-match-graph}
    \State Compute an $M_x$-saturating matching $P$ of $H$. \label{step:bpt-det-va-edgecol-compute-matching}
    \For{each $e \in M_x$}
      \State Assign color $P(e)$ to $e$
      \If{$d_{x,y} < \frac{1}{16} s$}
        \State Remove $\sigma_y^{-1} - (b_y - 1)s$ from $Q_y$
      \EndIf
    \EndFor
    \For{each $y \in B$ with $d_{x,y} > 0$}
      \If{$d_{x,y} < \frac{1}{16} s$}
        \If{$|Q_y| \le s - \frac{1}{2^{17}} s$}
          \State $b_y \gets b_y + 1$ \label{step:bpt-det-va-edgecol-small-block}
          \State $Q_y \gets [s]$
        \EndIf
      \Else
        \State $Q_y \gets [s]$
        \State $b_y \gets b_y + \ceil{\frac{2 d_{x,y}}{s}} + 1$\label{step:bpt-det-va-edgecol-large-block}
      \EndIf
    \EndFor

  \end{algorithmic}
\end{algorithm}

This algorithm maintains, for each vertex $v\in B$, two variables $b_v$ and $Q_v$ that
indicate which colors in $[C]$ are certainly available for that vertex. It ensures that
that none of the colors in the set $\Xi_v = \{\sigma_v[(b_v - 1) s)] : i \in Q_v\} \sqcup \{\sigma_v[j] : j > b_v s\}$ have been used. When a new vertex $x$ in $A$ arrives, along with the multiset $M_x$
of edges adjacent to it, the algorithm selects a set $F_y$ indicating candidate colors $\sigma_y[F_y]$ for each $y$ adjacent to $x$, and computes a matching between the edges in $M_x$ and the
set of all colors, allowing each edge in $M_x$ only the colors corresponding to the edges endpoint in $B$. This matching ensures that all edges incident to $x$ receive different colors;
and for all $y \in B$, the use of the set $F_y$ to constrain the set of candidate colors
to a subset of $\Xi_v$ ensures that all incident to $y$ receive different colors.

For a given vertex $y$, as the algorithm runs, $b_y$ will be increased, by either Line \ref{step:bpt-det-va-edgecol-small-block} or \ref{step:bpt-det-va-edgecol-large-block}. Line \ref{step:bpt-det-va-edgecol-small-block} only triggers when $|Q_y| \le s - \frac{1}{2^{17}} s$, which requires that vertex $y$ has received $\ge \frac{1}{2^{17}} s$ incident edges since the last time $b_y$ was increased. Since there will be at most $\Delta$ edges incident to $y$, the total increase to $b_y$ from this line over the course of the algorithm will be $\le \Delta / (\frac{1}{2^{17}} s) = 2^{17} \Delta / s$. On the other hand, Line \ref{step:bpt-det-va-edgecol-small-block} only triggers when $d_{x,y}\ge \frac{1}{16} s$, and then increases $b_y$ by $\ceil{64 d_{x,y} / s} + 1$. Since $\sum_{x \in A} d_{x,y} \le \Delta$,
\begin{align*}
  \sum_{x \in A : d_{x,y} > \frac{1}{16} s} \left(\ceil{\frac{64 d_{x,y}}{s}} + 1\right)
  \le \sum_{x \in A : d_{x,y} > \frac{1}{16} s} \left(\frac{64 d_{x,y}}{s} + 2\right) \le \sum_{x \in A : d_{x,y} > \frac{1}{16} s} \frac{96 d_{x,y}}{s}  \le \frac{96 \Delta}{s}
\end{align*}
Thus, the total increase in $b_y$ will be $\le (2^{17}+96) \Delta / s$, and $b_y$ will always be $\le (2^{17}+97) \Delta / s$. Looking at the construction
of the set $F_y$ on Lines \ref{step:bpt-det-va-edgecol-low-deg-fy} and \ref{step:bpt-det-va-edgecol-high-deg-fy}, we see that it will only ever contain elements which are $\le (2^{17}+98) \Delta$. Since $C = 2^{18} \Delta \ge (2^{17}+98) \Delta$, it follows that computing $\sigma_y[F_y]$ will never index out of range.

The only remaining way this algorithm could fail is if Line \ref{step:bpt-det-va-edgecol-compute-matching}
were to report that no $M_x$-saturating matching exists. We will show that, if the 
$(\sigma_v)_{v \in B}$ are drawn from $(\epsilon,s)$-wise independent distributions,
then probability $\ge 1 - \delta$, for all possible
sets $M_x$ and combinations of "free slots", $(F_y)_{y : d_{x,y} >0}$, Hall's condition will
hold on the graph $H$ constructed on Line \ref{step:bpt-det-va-edgecol-match-graph}.

Since whether the constructed graph $H$ has a matching does not depend on the value of $x$, only on the number of edges arriving at a given $y \in B$, we do not need to take a union bound over all possible sets $M_x$. Instead, define a configuration by a tuple $(S,(d_y)_{y \in S},(b_y)_{y \in S},(Q_y)_{y \in S})$. The set $S$ gives the neighborhood of $x$, and for each $y \in S$ we set $d_y = d_{x,y}$. The values $b_y,Q_y$ match the values from the algorithm at the time $M_x$ arrives. Note that the set $F_y$ is a function of $b_y$, $Q_y$, and $d_y$, and for fixed $b_y,Q_y$ is monotone increasing as a function of $d_y$. We do \emph{not} need any extra cases to handle Hall's condition for subsets of $M_x$; consider any subset $M_x' \subseteq M_x$, and let $S',d_{y}',F_y'$ correspond to $M_x'$. Then because $F_y' \subseteq F_y$ for each $y \in S'$, if Hall's condition holds for the configuration $(S',(d_y')_{y \in S'},(b_y)_{y \in S'},(Q_y)_{y \in S'})$, then
\begin{align*}
  \left|\bigcup_{y \in S'} F_{y}\right| \ge \left|\bigcup_{y \in S'} F_{y}'\right| \ge \sum_{y \in S'} d_y'
\end{align*}
which implies that Hall's condition also holds for the subset $M_x'$ within the bipartite graph $H$ constructed for $M_x$.




Let $d = \sum_{y \in S} d_y$. If the permutations $(\sigma_y)_{y\in B}$ were each chosen uniformly at random, it would be straightforward to prove that Hall's condition fails for each configuration $(S,(d_y)_{y \in S},(b_y)_{y \in S},(Q_y)_{y \in S}$ with probability $\le e^d (d/C)^{\Theta(|S| s + d)}$, after which a union bound over configurations gives a $\le \delta$ total failure probability. However, because we assume the $(\sigma_y)_{y\in B}$ are only $(\epsilon,s)$-wise independent, we will need a more precise argument.

Each configuration $(S,(d_y)_{y \in S},(b_y)_{y \in S},(Q_y)_{y \in S}$ can be split into $O(\log \Delta)$ different "level configurations". Let $\tau = s / 16$; then for each vertex $y$, if $d_y < \tau$, the algorithm will choose $F_y$ using Line \ref{step:bpt-det-va-edgecol-low-deg-fy} to be a subset of size $\le s$ and $\ge s (1 - 2^{-17}) \ge s / 2$; and if $d_y \ge \tau$, the algorithm will choose $F_y$ using Line \ref{step:bpt-det-va-edgecol-high-deg-fy}, to be a subset of size $\ge 64 d_y$. Define $L_0 = \{y \in S : d_y < \tau\}$. For each $\ell \in \{1,\ldots,\lambda\}$, for $\lambda = \ceil{\log{\Delta}}$ let $L_\ell = \{y \in S : 2^{\ell - 1} \tau \le d_y < 2^{\ell} \tau\}$. Also write $L_{> \ell} = \bigcup_{j > \ell} L_j$. Within each "level", the values of $d_y$ are either all small ($< \tau$), or all within a factor $2$ of each other. We will show that with high probability, the following two conditions hold:
\begin{align}
  \forall \ell \ge 1, \forall (L_\lambda,\ldots,L_{\ell+1}) \text{ where } \max_{i > \ell} {(3/2)^{i - \ell} |L_i|} \le |L_\ell|,& \forall {d_y,b_y,Q_y \text{ for } y \in \bigsqcup_{j \ge \ell} L_\ell} : \nonumber\\
  & \left| \left(\bigcup_{y \in L_\ell} \sigma_y[F_y]\right) \setminus \left(\bigcup_{y \in L_{> \ell}} \sigma_y[F_y]\right) \right| \ge 8 \sum_{y \in L_0} d_y \label{eq:hall-abundant} \\

  \forall (L_\lambda,\ldots,L_1) \text{ where } \max_{i > 0} {(3/2)^{i} |L_i|} \le |L_0|, & \forall {d_y,b_y,Q_y \text{ for } y \in \bigsqcup_{j \ge 0} L_\ell} : \nonumber \\
  & \left| \left(\bigcup_{y \in L_0} \sigma_y[F_y]\right) \setminus \left(\bigcup_{y \in L_{> 0}} \sigma_y[F_y]\right) \right| \ge \sum_{y \in L_0} d_y \label{eq:hall-end-ok}
\end{align}
Then for the specific configuration $(S,(d_y)_{y \in S},(b_y)_{y \in S},(Q_y)_{y \in S})$, let $A \subseteq \{0,\ldots,\lambda\}$ contain all $\ell$ for which $|L_\ell| \ge \max_{i > \ell} (3/2)^{i-\ell}|L_i|$. Because the condition of Eq. \ref{eq:hall-abundant} holds for all $i \in A$ with $i > 0$, these "levels" of the configuration are associated with enough entries of $C$ that they "pay for" all levels with smaller degrees that also do not have many more vertices. Level $L_0$ pays for itself if $0 \in A$, by Eq. \ref{eq:hall-end-ok}. Formally, we have:
\begin{align*}
  |\bigcup_{y \in S} \sigma_y[F_y]| &= \sum_{i \in \{0,\ldots,\lambda \}} | (\bigcup_{y \in L_i} \sigma_y[F_y]) \setminus (\bigcup_{y \in L_{> i}} \sigma_y[F_y]) |  \\
    &\ge \sum_{i \in A} | (\bigcup_{y \in L_i} \sigma_y[F_y]) \setminus (\bigcup_{y \in L_{> i}} \sigma_y[F_y]) | \\
    &\ge 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} 8 \sum_{y \in L_i} d_y \\
    &\ge 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} 8 \cdot 2^{i - 1} \tau |L_i| \\
    &= 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} 4 \cdot 2^{i} \tau |L_i| \\
    &\ge 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} \sum_{j \le i} \left(\frac{3}{4}\right)^{i - j} \left(2^{i} \tau |L_i|\right)  \\
    &\ge 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} \sum_{j \le i : |L_j| \le (3/2)^{i - j}|L_i|}  2^{j} \tau \left(\frac{3}{2}\right)^{i - j} |L_i|  \\
    &\ge 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} \sum_{j \le i : |L_j| \le (3/2)^{i - j}|L_i|}  2^{j} \tau |L_j| \\
    &\ge 1_{0 \in A} \left(\sum_{y \in L_0} d_y\right) + \sum_{i \in A \setminus \{0\}} \sum_{j \le i : |L_j| \le (3/2)^{i - j}|L_i|}  \sum_{y \in L_j} d_y  \\
    &=  \sum_{i \in \{0,\ldots,\lambda\}} \sum_{y \in L_j} d_y = \sum_{y \in S} d_y
\end{align*}

We first observe that Eq. \ref{eq:hall-abundant} matches the conditions for \Cref{lem:approx-indep-large-anticoncentration}. Specifically, if $y \in L_\ell$ for $\ell > 1$, then $d_y \ge s / 16$, and we have both $|F_y| \ge s$ and $|F_y| \ge 64 d_y$. Also, since the $d_y \in [2^{\ell-1} \tau, 2^\ell \tau)$, we will have $\max_{y \in L_\ell} |F_y| \le 2 \min_{y \in L_\ell} F_y$. Letting $X = \bigcup_{y \in L_{> i}} \sigma_y[F_y]$, we have $|X| \le \sum_{y \in L_{> i}} |F_y| \le \sum_{y \in L_{> \ell}} (2s + 64 d_y) \le 96 \Delta \le \frac{1}{8} C$ . Similarly, $\sum_{y \in L_{\ell}} \sigma_y[F_y] \le 96 \Delta \le \frac{1}{2} C$. Thus, \Cref{lem:approx-indep-large-anticoncentration} applies, and gives an $\exp(- O(s |L_\ell|))$ upper bound on the probability that $|\bigcup_{y \in L_\ell} \sigma_y[F_y] \setminus X| \ge 4 \sum_{y \in L_0} d_y$.

For Eq. \ref{eq:hall-end-ok}, if $\sum_{y \in L_0}{|F_y|} \ge \frac{1}{2} C$, we apply \Cref{lem:approx-indep-small-anticoncentration}. As argued above, the set $X = \bigcup_{y \in L_{> 0}} \sigma_y[F_y]$ will have size $\le \frac{1}{8} C$. If the bad event in \Cref{lem:approx-indep-small-anticoncentration} does not hold, then the condition in Eq. \ref{eq:hall-end-ok} will, since $\sum_{y \in L_0} d_y \le \Delta \le \frac{1}{16} C$. On the other hand, if $\sum_{y \in L_0}{|F_y|} < \frac{1}{2} C$, we apply \Cref{lem:approx-indep-large-anticoncentration}; this works because we have $|F_y| \ge (1 - 2^{-17}) s \ge \frac{1}{2} s$.

Since \Cref{lem:approx-indep-large-anticoncentration}  and \Cref{lem:approx-indep-small-anticoncentration} both ensure a $\exp( - \Omega(s |L_i|))$ type upper bound for the probability of conditions from Eqs. \ref{eq:hall-abundant} and \ref{eq:hall-end-ok}, we can bound the probability that none of the individual event fails in a single sum. Since for each $y$, $Q_y$ is refreshed after at least $s/2^{17}$ elements are removed from it, there are only $\sum_{i=0}^{\ceil{s/2^{17}}} \binom{s}{i} \le 2^{s H(1/2^{16})} \le \exp(s / 2^{11})$ possible values for $Q_y$; here $H$ is the binary entropy function.
\begin{align*}
  \Pr &[\text{Eqs. \ref{eq:hall-abundant} and \ref{eq:hall-end-ok} hold}]  \\
    &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \sum_{\underset{\text{all $|L_j| \le (2/3)^{j - \ell} w$}}{L_\lambda,\ldots,L_\ell}} \sum_{(d_y,b_y,Q_y)_{y \in \bigsqcup_{j \ge \ell} L_j}} \exp(-  s w / 2^9) \\
    &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \prod_{j \ge \ell} \left((n+1) C^2 \exp(s/2^{11})\right)^{(2/3)^{j - \ell} w} \exp(-  s w / 2^9) \\
    &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \left((n+1) C^2 \exp(s / 2^{11}) \right)^{3 w} \exp(- s w / 2^9)  \\ 
    &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \left(n C\right)^{6 w} \exp(- s w / 2^{11}) \qquad  \text{since $(n+1) \le n^2$ and $2^{-9} - 3 \cdot 2^{-11} = 2^{-11}$} \\ 
    &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \exp(- s w / 2^{12}) \qquad \text{since $s \ge 6 \cdot 2^{12} (18 + \log(n \Delta)) \ge 6 \cdot 2^{12} \ln(n C)$} \\
    &\le (\lambda + 1) \Delta \exp(-s / 2^{12}) \le \delta \qquad \text{since $s \ge 2^{13} \log(\Delta/\delta) \ge 2^{13} \ln(\Delta/\delta)$}
\end{align*}
Thus,
\begin{align*}
  \Pr[\text{any configuration fails Hall's condition}]  \le \delta \,.
\end{align*}

\caption{Deterministic algorithm for $O(\Delta)$ edge coloring for (adversarial) one sided vertex arrival bipartite streams, using $\widetilde{O}(n)$ bits of advice\label{alg:bpt-det-va-edgecol}}
\begin{algorithmic}[1]
\Statex \textbf{Input}: Stream of vertex arrivals for $n$-vertex graph $G=(A \sqcup B,E)$ of max degree $\Delta$
  \Statex
  \Statex $\delta \in (0,1)$ is a parameter so that, if the advice is chosen randomly, it will work for all inputs with probability $\ge 1 - \delta$
  \Statex
  \Statex \underline{\textbf{Initialize}:}
  \Statex Let $C = 2^{18} \Delta$. 
  \Statex Let $s = \ceil{2^{18} \log\frac{n \Delta}{\delta}} $.
  \Statex Advice: $(\sigma_v)_{v \in B}$, where each $\sigma_v$ is a permutation over $[C]$. If chosen randomly, each is $(\epsilon,s)$-wise independent for $\epsilon \le C^{-s - 1}$

  \For{$v \in B$}
    \State $b_v \gets 1$.
    \State $Q_v \gets [s]$.
  \EndFor

\Statex \underline{\textbf{Process}(vertex $x$ with multiset $M_x$ of edges to $B$)}
  \Statex Let $d_{x,y}$ be the number of times edge $\{x,y\}$ is in $M_x$
  \For{each $y \in B$ with $d_{x,y} > 0$}
    \If{$d_{x,y} < \frac{1}{16} s$}
      \State Let $F_y = (b_y -1) s + Q_y$\label{step:bpt-det-va-edgecol-low-deg-fy}
    \Else
      \State Let $F_y = ((b_y -1) s + Q_y) \sqcup [b_y s, b_y + \ceil{\frac{64 d_{a,b}}{s}} s]$\label{step:bpt-det-va-edgecol-high-deg-fy}
    \EndIf
  \EndFor
  \State Construct bipartite graph $H$ from $M_x$ to $[C]$, edge $e \in M_x$
  is linked to all $c \in \sigma_y[F_y]$.\label{step:bpt-det-va-edgecol-match-graph}
  \State Compute an $M_x$-saturating matching $P$ of $H$. \label{step:bpt-det-va-edgecol-compute-matching}
  \For{each $e \in M_x$}
    \State Assign color $P(e)$ to $e$
    \If{$d_{x,y} < \frac{1}{16} s$}
      \State Remove $\sigma_y^{-1} - (b_y - 1)s$ from $Q_y$
    \EndIf
  \EndFor
  \For{each $y \in B$ with $d_{x,y} > 0$}
    \If{$d_{x,y} < \frac{1}{16} s$}
      \If{$|Q_y| \le s - \frac{1}{2^{17}} s$}
        \State $b_y \gets b_y + 1$ \label{step:bpt-det-va-edgecol-small-block}
        \State $Q_y \gets [s]$
      \EndIf
    \Else
      \State $Q_y \gets [s]$
      \State $b_y \gets b_y + \ceil{\frac{2 d_{x,y}}{s}} + 1$\label{step:bpt-det-va-edgecol-large-block}
    \EndIf
  \EndFor

\end{algorithmic}

