  \end{align*}

\caption{Storing free regions from a permutation\label{alg:ds-rand-blocks}}
\begin{algorithmic}[1]
  \Statex \underline{$F \gets $\textbf{InitFreeTracker}($C$,$s$,$\Delta$,$\sigma$\textbf{):}} \Comment{Assume $C$,$s$,$\Delta$ are powers of two, and $\sigma$ permutation of $[C]$, and $C \ge \Delta$}
  \State $H \gets [s]$ be a subset of $[s]$
  \State $b \gets 1$ be a counter between $1$ and $C/s$

  \State \textcolor{PineGreen}{Optional: $Q \gets \emptyset$ is a set of references to objects}


  \Statex

  \Statex \underline{\textbf{Interpreting $F$ as subset of $[C]$}}
  \State \textbf{return} $\sigma[H + (b -1) s]$
  \Statex


  \Statex \underline{$F$\textbf{.RemoveAndUpdate(}$c$, \textcolor{PineGreen}{optional: $o$}\textbf{)}} \Comment{Requires $c \in F_v$}
  \State $H \gets H \setminus \{ \sigma^{-1}(c)  \}$
  \State \textcolor{PineGreen}{Optional: Add a reference to $o$, and store it in $Q$}
  \If{$|H| \le s - s\Delta /C$} \Comment{Switch to next block}
    \State $H \gets [s]$
    \State $b \gets b + 1$
    \State \textcolor{PineGreen}{Optional: Drop all references in $Q$ and set $Q \gets \emptyset$}
  \EndIf
\end{algorithmic}

\label{thm:online-rand-ea-formal}
Given any adversarial edge-arrival stream of a simple graph, there is a randomized algorithm for online $O(\Delta)$-edge-coloring using $O(n \sqrt{\Delta \log n})$ bits of space
and $\widetilde{O}(n \sqrt{\Delta})$ oracle random bits.

We will show that \Cref{alg:rand-ea-edgecol} satisfies the claims of the lemma, if $\Delta = \Omega(\log (n/\delta))$. (For smaller values of $\Delta$, fall back to \Cref{alg:simple-greedy}.) In the following argument, we shall assume that the permutations $(\sigma_v)_{v\in S}$ are $s$-wise independent. The pseudocode states $(\epsilon,s)$-wise independence, since that is attainable per \Cref{lem:fast-permutations} using only $O(s \mathrm{poly}(\log 1/\epsilon, \log s))$ bits of randomness per permutation. This will not affect the validity of the proof, since it at most increases the probabilities of events $H_{\{u,v\}}$ and $J_{u,v}$ defined later by $\epsilon$, which is polynomially smaller than the losses in the argument due to bounding the number of events by $n^2$ instead of $\binom{n}{2}$ or $n^2 - n$. We also assume that $\Delta$ is a power of two; if not, we can increase $\Delta$ to the nearest power of two, and the algorithm will still give an $O(\Delta)$ coloring.

 Each color tracker $F_v$ can be stored using $O(\log \Delta)$ bits for $b$, and $O(s)$ bits for $H$; thus 
 \Cref{alg:rand-ea-edgecol}  will use $O(n (s + \log \Delta)) = O(n \sqrt{\Delta \log (n/\delta)})$ bits in total.
 For $\Delta = O(\log (n/\delta))$, the \Cref{alg:simple-greedy} uses $O(n \Delta)$ bits, which is also $O(n \sqrt{\Delta \log (n/\delta)})$.


 \begin{algorithm}[htb!]
   \caption{Randomized algorithm for $O(\Delta)$ edge coloring for simple graph edge arrival streams\label{alg:rand-ea-edgecol}}
   \begin{algorithmic}[1]
   \Statex \textbf{Input}: Stream of vertex arrivals $n$-vertex graph $G=(A \sqcup B, E)$
   \Statex Assume $\Delta$ is a power of two, and $\Delta = \Omega(\log(n/\delta))$
     \Statex
     \Statex \underline{\textbf{Initialize}:}
     \State Let $C = 128 \Delta$
     \State Let $s$ be the least power of two which is $\ge 128 \sqrt{\Delta \log (n/\delta)}$
     \State Let $\mathcal{H}$ be an ($\epsilon,s$)-wise independent distribution of permutations on $[C]$, with $\epsilon \le \exp(-s^2/C) \le (\delta/n)^{128}$

     \For{$v \in B$}
       \State Let $\sigma_v$ be a random permutation from $\mathcal{H}$
       \State $F_v \gets \textsc{InitFreeTracker}(C, s, \Delta, \sigma_v)$, without reference count tracking
     \EndFor
   \Statex 

   \Statex 
   \Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color}}
     \If{$F_x \cap F_y = \emptyset$}
       \State abort
     \EndIf

     \State Let $c$ be chosen uniformly at random from $F_x \cap F_y$.\label{step:rand-ea-edgecol-pick-color}
     \State $F_x.\textsc{RemoveAndUpdate(c)}$
     \State $F_y.\textsc{RemoveAndUpdate(c)}$
     \State \textbf{return} color $c$
   \end{algorithmic}
 \end{algorithm}

 For each $v \in V$, $i \in [C/s]$, write $P_{v,i}$ for the set $\sigma[[s] + (i -1) s]$ of the free region tracker $F_v$ for vertex $v$. (See \Cref{alg:ds-rand-blocks}.) Since we are assuming the $\sigma_v$ are $s$-wise independent, the set $P_{v,i}$ will be uniformly distributed over over $\binom{[C]}{s}$.

 Consider a fixed input stream $e_1,e_2,\ldots$, where the edges of the stream together form the simple graph $G$. Write $b_{x,\{u,v\}}$ for the value of the counter $b$ inside $F_x$ just before the algorithm processed edge $\{u,v\}$. Let $D_{\{u,v\}} := P_{u, b_{u,\{u,v\}}} \cap P_{v, b_{v,\{u,v\}}}$. Also define $M_{u,v} := \{ x : \{x,u\} \in G \land b_{u,\{x,u\}} = b_{u,\{u,v\}} \land \{x,u\} \prec \{u,v\}\}$; this is the set of vertices which were adjacent to $u$, for which the edge $\{x,u\}$ was added before $\{u,v\}$, and while the value of the counter $b$ inside $F_u$ for vertex $u$ was the same as it was at the time $\{u,v\}$ was added. This is the set of vertices whose color
 choices \emph{might} reduce the size of $F_u \cap F_v$ at the time $\{u,v\}$ is added. 

 We will first show that of the following two classes of $m$ events, the probability that any of the events is true is $\le \delta / 2$.
 \begin{align*}
   \forall \{u,v\} \in G: H_{\{u,v\}} & := \left\{ D_{\{u,v\}} \le \frac{1}{2} s^2/C \right\} \\
   \forall (u,v) \text{ where } \{u,v\} \in G: J_{u,v} & := \left\{ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge  2 \cdot \frac{3}{2} \frac{s^3}{C^2} \frac{\Delta s}{C} \right\} \\
 \end{align*}

 To bound the probability of $H_{\{u,v\}}$, we let $X_1,\ldots,X_C$ be indicator random variables where $X_i = 1$ iff $i \in P_{u, b_{u,\{u,v\}}}$.  Since the $X_i$ are negatively associated\cite{JoagDevP83}, the proof of the Chernoff bound holds, and 
 \begin{align*}
   \Pr[ |D_{\{u,v\}}| \le \frac{1}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
      &= \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
      &\le \exp( - \frac{1}{8} \mathbb{E}[D_{\{u,v\}}])= \exp(- \frac{s^2}{8 C} )  \\
      &\le \exp(- 16 \log\frac{n}{\delta}) \le \frac{\delta}{2 n^2}
 \end{align*}

 To bound the probability of the events $\{J_{u,v}\}$, we will show that $|D_{u,v}|$ is not too large w.h.p, and conditioned on that, the sum $\sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}|$ is not too large w.h.p. With $\{X_i\}_{i\in[C]}$ as defined above:
 \begin{align*}
   \Pr[ |D_{\{u,v\}}| \ge \frac{3}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
      &\le  \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
      &\le \exp( - \frac{1}{10} \mathbb{E}[D_{\{u,v\}}]) = \exp(- \frac{s^2}{10 C} ) \\
      &\le \exp(- \frac{128}{10} \log\frac{n}{\delta})\le \frac{\delta}{4 n^2}
 \end{align*}
 The permutations $\{\sigma_x\}_{x \in M_{u,v}}$ are independent of $\sigma_u$ and $\sigma_v$. For each $x \in M_{u,v}$, let $Y_{1,x},\ldots,Y_{C,x}$ be indicator random variables
 where $Y_{i,x}$ is 1 iff $i \in P_{x, b_{x,\{x,u\}}}$, and zero otherwise. Due to the frequency of free color buffer refreshing, $|M_{u,v}| \le s \Delta / C$; and since $|P_{x, b_{x,\{x,u\}}}| = s$, $\mathbb{E} Y_{i,x} = s/C$. Since the $\{Y_{i,x}\}_{i \in D_{\{u,v\}}, x \in M_{u,v}}$ are negatively associated, we can apply a Chernoff bound. If we assume that $|D_{\{u,v\}}| \le \frac{3 s^2}{2 C}$, then we have:
 \begin{align*}
   \Pr\left[ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C}\right]
     &= \Pr\left[ \sum_{i \in D_{\{u,v\}}, x \in M_{u,v}} Y_{i,x} \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right] \\
     &\le \exp\left( - \frac{1}{8} \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right) \\
     &\le \exp(- 12 (\log(n/\delta))^2) \le \frac{\delta}{4 n^2}
 \end{align*}
 Thus, the probability that either $|D_{\{u,v\}}| \ge \frac{3 s^2}{2 C}$ or event $J_{u,v}$ does not hold is $\frac{\delta}{2 n^2}$.

 For the rest of the proof, we will consider the case where none of the events $J_{u,v}$ or $H_{\{u,v\}}$ holds; this happens with probability $\ge 1 - \delta/2$. Fix values of the $(\sigma_v)_{v\in V}$ satisfying none of the events. The only other random decisions made
 by the algorithm are the choices made on Line \ref{step:rand-ea-edgecol-pick-color}, randomly choosing the edge color $\chi_{\{u,v\}}$ for $\{u,v\}$ from $F_u \cap F_v$. We will prove by induction on
 the number of edges processed that the probability of $|F_u \cap F_v| \le \frac{1}{4} s^2 / C$ holding at the time Line \ref{step:rand-ea-edgecol-pick-color} is executed, in total over all $t$ edges so far is, $\le \delta \cdot t / (2n^2)$.

 To do this, we will use the following lower bound:
 \begin{align}
   |F_u \cap F_v| \ge |D_{\{u,v\}}| - \sum_{x \in M_{u,v}} W_{x,u} - \sum_{x \in M_{u,v}} W_{x,v} \label{eq:fuv-lb}
 \end{align}
 Here $W_{x,u}$ is the indicator random variable for the event that the color chosen for
 $\{x,u\}$ was in $D_{\{u,v\}}$. The lower bound overcounts the number of colors in $D_{\{u,v\}}$ that have been removed from $F_u \cap F_v$.

 The base case of the induction (0 edges) is immediate. Assume that we are processing
 edge $\{u,v\}$, and that all edges $\{x,y\}$ earlier in the stream, when they were processed,
 had $|F_x \cap F_y| \ge \frac{s^2}{4 C}$. For each $x \in M_{u,v}$, the color $\chi_{\{x,u\}}$ was drawn uniformly at random from \emph{some} set $F_x \cap F_u$, which we assume satisfies $|F_x \cap F_u| \ge \frac{s^2}{4 C}$. For any subset $H$ of $D_{\{x,u\}}$ of size $\frac{s^2}{4 C}$, if $\hat{\chi}$ is chosen u.a.r. from $H$, then 
 \begin{align*}
   \Pr[\hat{\chi} \in D_{\{u,v\}}] \le \frac{|H \cap D_{\{u,v\}}|}{|H|} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|
 \end{align*}
 Conditioned on the color choices of all earlier edges, we thus have $\mathbb{E} W_{x,u} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|$. Thus
 \begin{align*}
   \mathbb{E}\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v}\right] &\le \frac{4 C}{s^2} \left(\sum_{x \in M_{u,v}}  |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}| + \sum_{x \in M_{v,u}}  |P_{x,b_{x,\{x,v\}}} \cap D_{\{u,v\}}| \right) \\
     &\le \frac{4 C}{s^2} \cdot 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} = 12 \frac{\Delta}{C} \frac{s^2}{C} < \frac{s^2}{8 C} & \text{since $\Delta \le C / 128$}
 \end{align*}

 By the multiplicative/Chernoff-like formulation of Azuma's inequality,
 \begin{align*}
   \Pr&\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v} \ge \frac{s^2}{4 C}\right] \\
     &\le \exp( -\frac{1}{3} \frac{s^2}{4 C}) \le \exp\left( - \frac{32}{3} \log\frac{n}{\delta} \right) \le \frac{\delta}{2 n^2}
 \end{align*}
 By a union bound over all edges, the probability that any edge $\{u,v\}$ has $|F_u \cap F_v| \le \frac{s^2}{4 C}$ is $\le \delta / 2$.

 We have shown that, in total, the probability of the algorithm aborting because
 $F_u \cap F_v = \emptyset$ is $\le \delta$.

\begin{align*}
    \forall \{u,v\} \in G: H_{\{u,v\}} & := \left\{ D_{\{u,v\}} \le \frac{1}{2} s^2/C \right\} \\
    \forall (u,v) \text{ where } \{u,v\} \in G: J_{u,v} & := \left\{ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge  2 \cdot \frac{3}{2} \frac{s^3}{C^2} \frac{\Delta s}{C} \right\} \\
  \end{align*}

\begin{align*}
    \Pr[ |D_{\{u,v\}}| \le \frac{1}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &= \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le \exp( - \frac{1}{8} \mathbb{E}[D_{\{u,v\}}])= \exp(- \frac{s^2}{8 C} )  \\
       &\le \exp(- 16 \log\frac{n}{\delta}) \le \frac{\delta}{2 n^2}
  \end{align*}

\begin{align*}
    \Pr[ |D_{\{u,v\}}| \ge \frac{3}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le  \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le \exp( - \frac{1}{10} \mathbb{E}[D_{\{u,v\}}]) = \exp(- \frac{s^2}{10 C} ) \\
       &\le \exp(- \frac{128}{10} \log\frac{n}{\delta})\le \frac{\delta}{4 n^2}
  \end{align*}

\begin{align*}
    \Pr\left[ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C}\right]
      &= \Pr\left[ \sum_{i \in D_{\{u,v\}}, x \in M_{u,v}} Y_{i,x} \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right] \\
      &\le \exp\left( - \frac{1}{8} \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right) \\
      &\le \exp(- 12 (\log(n/\delta))^2) \le \frac{\delta}{4 n^2}
  \end{align*}

\begin{align}
    |F_u \cap F_v| \ge |D_{\{u,v\}}| - \sum_{x \in M_{u,v}} W_{x,u} - \sum_{x \in M_{u,v}} W_{x,v} \label{eq:fuv-lb}
  \end{align}

\begin{align*}
    \Pr[\hat{\chi} \in D_{\{u,v\}}] \le \frac{|H \cap D_{\{u,v\}}|}{|H|} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|
  \end{align*}

\begin{align*}
    \mathbb{E}\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v}\right] &\le \frac{4 C}{s^2} \left(\sum_{x \in M_{u,v}}  |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}| + \sum_{x \in M_{v,u}}  |P_{x,b_{x,\{x,v\}}} \cap D_{\{u,v\}}| \right) \\
      &\le \frac{4 C}{s^2} \cdot 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} = 12 \frac{\Delta}{C} \frac{s^2}{C} < \frac{s^2}{8 C} & \text{since $\Delta \le C / 128$}
  \end{align*}

\begin{align*}
    \Pr&\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v} \ge \frac{s^2}{4 C}\right] \\
      &\le \exp( -\frac{1}{3} \frac{s^2}{4 C}) \le \exp\left( - \frac{32}{3} \log\frac{n}{\delta} \right) \le \frac{\delta}{2 n^2}
  \end{align*}

We will prove this in two steps. First, define a specific property U 
that the $(\sigma_v)_{v\in V}$ should satisfy with probability $\ge 1 - \delta$; second, prove that if this property holds, then any graph $H$ can be colored.

The permutations $(\sigma_v)_{v\in V}$ satisfy property U if:
\begin{itemize}
  \item For all pairs $(u,i),(v,j) \in V \times [C/s]$, with $u \ne v$, we have $|P_{u,i} \cap P_{v,i}| \ge \frac{s^2}{2 C}$.
  \item For each $(u,i) \in V \times [C/s]$, $S \subseteq (V \setminus \{s\}) \times [C/s]$ where $|S| \le s \Delta / C$ and $S$ includes no two vertices $(v,i),(u,j)$ with $v = u$, and all $T \in \binom{P_{u,i}}{|S| - 1}$, there exists some $(x,j) \in S$ for which $|P_{x,j} \cap T| < \frac{1}{10} |P_{x,j} \cap P_{u,i}|$. (This is, in effect, a stronger version of Hall's condition).
\end{itemize}

For the first part of property $U$, it is straightforward to bound the probability that it does not hold. For a given pair $(u,i),(v,j) \in V \times [C/s]$, $u\ne v$, because the permutations are $(\epsilon,s)$-wise independent, the sets $P_{u,i}$ and $P_{v,j}$ are within $\epsilon$-total-variation distance of being uniformly random subsets of $[C]$ of size $s$, we can apply a Chernoff bound for the number of elements in $P_{u,i}$ that lie in $P_{v,j}$:
\begin{align}
  \Pr[ P_{u,i} \cap P_{v,j} \le \frac{1}{2} \frac{s^2}{C} ] \le \exp( -\frac{1}{8}  \frac{s^2}{C} ) + \epsilon \le \exp( - 2^{10} \log (n/\delta)) + \epsilon \le \frac{\delta}{2 n^2} \label{eq:puv-size-lb}
\end{align}
(The additive factor $\epsilon$ accounts for the maximum difference in probabilities for this event between the case where $P_{u,i}$ is exactly uniform and the case where it is $\epsilon$-far from such.)

For the second part, consider a specific combination $(u,i,S,T)$, and fix $P_{u,i}$. Then the probability that this combination violates property U is:
\begin{align}
  \Pr\left[ \bigwedge_{(x,j) \in S} \left\{ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i}\right\} \right] \le \prod_{(x,j) \in S} \Pr_{P_{x,j}}\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \right] \label{eq:superhall-specific}
\end{align}
since the $P_{x,j} \in S$ are all independent, since $S$ contains at most one entry for each $v \in V$. Since $P_{x,j}$ is a uniformly random subset $[C]$,
$P_{x,j} \cap P_{u,i}$ is symmetrically distributed over $P_{u,i}$. Now let $\hat{T}$ be a uniformly random element of $\binom{P_{u,i}}{s}$, and define indicator random variables $\{Y_k\}_{k \in P_{u,i}}$ so that $Y_k = 1$ iff $k \in \hat{T}$; these are negatively associated and $\mathbb{E}[Y_k] = \frac{|S| - 1}{s}$. Thus, if we assume $|P_{x,j} \cap P_{u,i}| = h$:
\begin{align*}
  \Pr_{P_{x,j}}&\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} |  \Big| |P_{x,j} \cap P_{u,i}| = h\right] \\
    &\le \Pr_{\hat{T}}\left[ |P_{x,j} \cap \hat{T}| \ge \frac{1}{10} h \Big| |P_{x,j} \cap P_{u,i}| = h \right] + \epsilon \\
    &= \Pr_{\{Y_k\}_{k \in P_{u,i}}}\left[ \sum_{k \in P_{u,i}} Y_k \ge \frac{1}{10} h \Big| |P_{x,j} \cap P_{u,i}| = h | \right] + \epsilon \\
    &\le \exp\left( -2 \left(\frac{1}{10} - \frac{|S| - 1}{s} \right)^2 h \right) + \epsilon \\
    &\le \exp\left( -2 \left(\frac{1}{10} - \frac{\Delta}{C} \right)^2 h \right) + \epsilon \le \exp\left( - h / 200 \right) + \epsilon  \qquad \text{since $C = 32 \Delta$}
\end{align*}
This bound is useful only if $h$ is large enough. By the law of total probability, and using the bound from Eq. \ref{eq:puv-size-lb} to handle the case where $h$ is small:
\begin{align*}
  \Pr_{P_{x,j}}&\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \right] \\
    &\le \Pr_{P_{x,j}}\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \Big| |P_{x,j} \cap P_{u,i}| \ge \frac{s^2}{2 C} \right]\Pr\left[|P_{x,j} \cap P_{u,i}| \ge \frac{s^2}{2 C}\right]
      + \Pr\left[|P_{x,j} \cap P_{u,i}| \le \frac{s^2}{2 C}\right] \\
      &\le (\exp\left( - \frac{s^2}{400C} \right) + \epsilon)\cdot 1 + (\exp(-\frac{s^2}{8 C}) + \epsilon)
      \le 2 \exp\left( - \frac{s^2}{400C} \right) \,.
\end{align*}

Substituting this result into Eq. \ref{eq:superhall-specific} gives:
\begin{align*}
  \Pr\left[ \bigwedge_{(x,j) \in S} \left\{ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i}\right\} \right] \le 2^{|S|} \exp\left( - |S| \frac{s^2}{400C} \right) \,.
\end{align*}
Taking a union bound over all $(u,i,S,T)$ tuples gives:
\begin{align*}
  \Pr&[\text{second part of Property U fails}] \\
    &\le \sum_{(u,i) \in V \times [C/s]} \sum_{k=1}^{s \Delta / C} \sum_{\text{valid $S$ with $|S| = k$}} \sum_{T \subseteq \binom{P_{u,i}}{k-1}} 2^{k} \exp\left( - k \frac{s^2}{400C}\right) \\
    &\le n \cdot \sum_{k=1}^{s \Delta / C} \cdot \binom{n - 1}{k} \left(\frac{C}{s}\right)^k \cdot \binom{s}{k - 1} \cdot 2^{k} \exp\left( - k \frac{s^2}{400C}\right) \\
    &\le n \sum_{k=1}^{s \Delta / C} \left( 2 n C s \exp\left(- \frac{s^2}{400 C}\right) \right)^k \\
    &\le 2 n \cdot 2 n C s \exp\left(- \frac{s^2}{400 C}\right) \qquad\qquad \text{for large enough $s^2/C$} \\
    & \le 4 n^2 \cdot (32 n)^2 \exp(- \frac{2048}{100} \log(n/\delta)) \le \frac{\delta}{2} \qquad\qquad \text{since $s \le C = 32 \Delta$}
\end{align*}
Combining this with a union bound over Eq. \ref{eq:puv-size-lb} implies that property U fails to hold with probability $\le \delta$.

For the second stage of the proof, we consider the following iterative process to color any graph $H$ satisfying the given conditions. Consider an arbitrary ordering $v_1,\ldots,v_n$ of the vertices in $V \times [C/s]$. For a given vertex $v_t$, let $A(v_t)$ be the set of vertices in $\{v_1,\ldots,v_{t-1}\}$ which are adjacent to $(v_t,i)$, and let $B(v_t,i)$ be the set of vertices in 
$\{v_{t+1},\ldots,v_{n}\}$ which are adjacent to $(v_t,i)$. For each $z \in A(v_t) \cup B(v_t)$, define $U_{t,v_t,z}$ to be the set of colors in $P_{v_t} \cap P_z$ that were already used by edges to vertices in $A(v_t)$ just \emph{after} step $t$. The color assignment chosen will maintain the invariant W that $|U_{t,z,(v_{t'})}| \le \frac{1}{3} |P_z \cap P_{v_{t'}}|$ for all $t' > t$ and $z \in A(v_{t'})$. In other words, that when it is time to color the edges from a future vertex $(v_{t'})$ to $A(v_{t'}$, only a $\le 1/3$ fraction of the initially possible color options will have been used.

Invariant W automatically holds when $t = 0$, since no edges have been colored. Say the invariant holds at time $t - 1$. Then we are guaranteed that $|U_{t-1,z,v_t}| \le \frac{1}{3} |P_z \cap P_{v_t}|$ for all $z \in A(v_t)$, and want to find color assignments for the edges from $A(v_t)$ to $z$ so that $|U_{t,z,v_t}| \le \frac{1}{3} |P_z \cap P_{v_t}|$ for all $z \in B(v_t)$. To do this, we will first pick a set $F \subseteq P_{v_t}$ that satisfies:
\begin{align}
  \forall x \in A(v_t):&\quad |P_x \cap P_{v_t} \setminus U_{t-1,x,v_t} \setminus F| \ge \frac{1}{10} |P_x \cap P_{v_t}| \label{eq:F-backward} \\
  \forall x \in B(v_t):&\quad |(P_y \cap P_{v_t}) \setminus F| \le \frac{1}{3} |P_y \cap P_{v_t}| \label{eq:F-forward} 
\end{align}
That such a set $F$ exists follows by the probabilistic method; say $F$ were chosen so that each element of $P_{v_t}$ is included u.a.r with probability $\frac{7}{10}$. For $i \in P_{v,t}$, let $X_i$ be the indicator random variable for the event that $i \in F$. Then the probability of Eq. \ref{eq:F-backward} is bounded by:
\begin{align*}
  \Pr&\left[ |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F| \ge \frac{1}{10} |P_x \cap P_{v_t}| \right] \\
    &\le   \Pr\left[ |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F|      \ge \frac{3}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \right] \quad \text{ since $|(P_x \cap P_{v_t}) \setminus U_{x,v}| \ge \frac{2}{3} |P_x \cap  P_{v_t}|$ } \\
    &\le \Pr\left[ \sum_{i \in (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}} X_i \ge \frac{17}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \right] \\
    &\le \exp\left(- \frac{9}{200} |P_x \cap P_{v_t} \setminus U_{t-1,x,v_t}| \right) \qquad \text{by Chernoff bound, since $\mathbb{E}$ of LHS is $\frac{14}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}|$} \\
    &\le \exp\left(- \frac{3}{100} |P_x \cap P_{v_t}| \right) \qquad \text{since $|(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \ge \frac{2}{3} |P_x \cap P_{v_t}|$} \\
    & \le \exp\left(-\frac{3 s^2}{200 C}\right) = \exp\left(- \frac{3072}{25} \log(n/\delta)\right) < \frac{1}{2 n}
\end{align*}
And for Eq. \ref{eq:F-forward}:
\begin{align*}
  \Pr\left[ |(P_x \cap P_{v_t}) \setminus F| \ge \frac{1}{3} |P_x \cap P_{v_t}| \right] 
    &= \Pr\left[ \sum_{i \in (P_x \cap P_{v_t})} X_i \le \frac{2}{3} |P_x \cap P_{v,t}| \right] \\
    &\le \exp\left( -2 \left(\frac{7}{10} - \frac{2}{3}\right)^2 |P_x \cap P_{v,t}| \right) \\
    &\le \exp\left(-\frac{1}{450} |P_y \cap P_v|\right) = \exp\left(-\frac{s^2}{900 C}\right) = \exp\left(- \frac{2048}{225} \log(n/\delta)\right) < \frac{1}{2n}
\end{align*}
Applying a union bound for the complements of Eq. \ref{eq:F-forward} and Eq. \ref{eq:F-backward} over all applicable $z$, we find that both conditions hold with positive probability, so a suitable $F$ exists.

Now that $F$ has been chosen, we will select the colors for the edges from $v_t$ to each $x \in A(v_t)$ from the set $(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F$. Since no colors in $F$ are chosen, for any $z \in B(v_t)$, $U_{t,z,v_t}$ will not contain any element of $F$; thus $|U_{t,z,v_t}| \le |(P_x \cap P_{v_t}) \setminus F| \le \frac{1}{3} |P_x \cap P_{v_t}|$.

Construct the bipartite graph $J$ between $A(v_t)$ and $P_{v_t}$, where $x \in A(v_t)$ has an edge to each of the colors in $(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F$. We claim there is an an $A(v_t)$-saturating matching $M$ of $J$; given this matching, we assign to edge $\{x,v_t\}$ its matched color $M(x)$. For all $x \in A(v_t)$, we will have $M(x) \in (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F$; since $M(x) \notin U_{t-1,x,v_t}$, the edge color for $\{x,v_t\}$ will not have been used before by any edge adjacent to $x$.
As the matching assigns a unique color to each edge, the edge coloring constraint will also be satisfied for $v_t$.

To prove there exists a matching $M$ in $J$, we verify that Hall's condition holds. For any subset $S$ of the vertices in $A(v_t)$, we want to show that
\begin{align*}
  \left| \bigcup_{x \in S} ((P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F) \right| \ge |S|
\end{align*}
The construction of $H$ ensures that $A(v_t)$ and all subsets thereof satisfy the conditions for the second part of Property U (Specifically, $|A(v_t)| \le s \Delta / C$, and that for any $b \in V$ there is at most one $j$ for which $(b,j) \in A(v,t)$.) By this property, we are guaranteed that for all $T \subseteq P_{v_t}$ of size $k-1$, that there exists some $x \in S$ for which $|P_x \cap T| \le \frac{1}{10} |P_x \cap P_{v_t}$. If Hall's condition does not hold for $S$, then there must exist some $T \subseteq P_{v,t}$ for which:
\begin{align*}
&\bigcup_{x \in S} ((P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F) \subseteq T \\
\implies \quad \forall x \in S:\quad & (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F \subseteq T \\
\implies \quad \forall x \in S:\quad & (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F \subseteq T \cap P_x \\
\implies \quad \forall x \in S:\quad & |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F| \le |T \cap P_x| \\
\implies \quad \forall x \in S: \quad& \frac{1}{10} |P_x \cap P_{v_t}| \le |T \cap P_x| \qquad \text{by Eq. \ref{eq:F-backward}}
\end{align*}
But by the second part of Property U, there must exist an $x \in S$ for which $\frac{1}{10} |P_x \cap P_{v_t}| > |T \cap P_x|$; this is a contradiction, so it follows that Hall's condition does hold for $S$. Since Hall's condition holds for all $S \subseteq A(v_t)$, $J$ will contain a matching, and step $t$ will ensure invariant W holds for step $t+1$.

By induction, it follows that invariant W holds for all $t \in [n]$, and thus that the process to color the edges of the graph will always work.

