\caption{Partial coloring algorithm: $(1/3)$-partial $O(\Delta)$ edge coloring for graph edge arrival streams satisfying Property Z, plus reference counting\label{alg:det-ea-partial}}
\begin{algorithmic}[1]
\Statex \textbf{Input}: Stream of edge arrivals $n$-vertex graph $G=(V,E)$. 
  \Statex Assume $\Delta$ is a power of two 

  \Statex
  \Statex \underline{\textbf{Initialize($\ell$,$\xi$,$\Delta$,$C$,$(\sigma_v)_{v \in V}$, $s$, $R$):}}
    \Statex Input $\Delta$ is the maximum degree of the input graph stream
    \Statex Input $C$ the number of colors this sketch will use
    \Statex Input $s$ is block size parameter, and $(\sigma_v)_{v \in V}$ are $s$-wise almost independent permutations
    \Statex Input $R$ is a reference counted pool of edges
    \Statex Each edge $e \in R$ will have associated counter $M^{(\ell)}_{e} \in [2^\ell]$ and color class $\chi^{(\ell)}_{e} \in \{0,\ldots,\ceil{\log_{3/2}{\Delta^{(\ell)}}}\} \times [C^{(\ell)}]$

    \For{$v \in V$}
      \State $F_v \gets \textsc{InitFreeTracker}(C,s,\Delta,\sigma_v)$. \Comment{Also referred to as: $F^{(\ell,\xi)}_v$}
    \EndFor

\Statex 
\Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{Option<color>} $\in \{\bot\} \cup [C]$}
  \If{$F_x \cap F_y \ne \emptyset$}\label{step:layer-color-test}
    \State Choose $c \in F_x \cap F_y$ arbitrarily\label{step:layer-color-choice}
    \State $F_x.\textsc{RemoveAndUpdate(c, $\{x,y\}$)}$ \Comment{This will increase $\{x,y\}$'s refcount in $R$}
    \State $F_y.\textsc{RemoveAndUpdate(c, $\{x,y\}$)}$
    \State $\chi^{(\ell)}_{\{x,y\}} \gets (\xi,c)$
    \State $M^{(\ell)}_{\{x,y\}} \gets 1$
    \State \textbf{return} color $c$
  \Else
    \State \textbf{return} $\bot$
  \EndIf
\end{algorithmic}

\caption{Inner algorithm:  $O(\Delta \log \Delta)$ edge coloring for graph edge arrival streams which have certain substreams satisfying Property Z, plus reference counting\label{alg:det-ea-inner}}
\begin{algorithmic}[1]
\Statex \textbf{Input}: Stream of edge arrivals $n$-vertex graph $G=(V,E)$. 
  \Statex Assume $\Delta$ is a power of two
  \Statex Superscript $\cdot^{(\ell)}$ indicates \emph{level} of algorithm

  \Statex
  \Statex \underline{\textbf{Initialize($\ell$, $\Delta^{(\ell)}$, $R$)}:}
    \Statex Input $\Delta^{(\ell)}$ is the maximum degree of the input graph
    \Statex Let $C^{(\ell)} = 32 \Delta^{(\ell)}$
    \State $D^{(\ell)} \gets \emptyset$ be a set of $O(n \log n)$ "overflow" edges 

    \If{ $\Delta^{(\ell)} \ge 256 \log(n/\delta))$}
      \Comment{Condition for \Cref{lem:offline-ea-coloring} to apply}
      \State Let $s^{(\ell)}$ satisfy constraints of \Cref{lem:offline-ea-coloring}
      \State Advice: $\{\sigma_v^{(\ell)}\}_{v \in V}$ are permutations over $[C^{(\ell)}]$, "good" for \Cref{lem:offline-ea-coloring}

      \For{each \emph{layer} $\xi \in [\ceil{\log_{3/2}{\Delta^{(\ell)}}}]$}
        \State $\mathfrak{I}^{(\ell,\xi)} \gets$ \textsc{Initialize}($\ell$,$\xi$,$\Delta$,$C$,$s$,$\{\sigma_v^{(\ell)}\}_{v\in V}$,$R$) from \Cref{alg:det-ea-partial}
      \EndFor
    \EndIf

\Statex 
\Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color} $\in \left[\ceil{\log_{3/2}{\Delta^{(\ell)}}}\right] \times \left[C^{(\ell)}\right]$}
    \If{$\Delta^{(\ell)} \ge 256 \log(n/\delta))$}
      \For{$\xi \in \left[\ceil{\log_{3/2}{\Delta^{(\ell)}}}\right]$}\label{step:loop-over-layers}
        \State Let $c \gets \mathfrak{I}^{(\ell,\xi)}.\textsc{Process}(\{x,y\})$ from \Cref{alg:det-ea-partial}
        \If{$c \ne \bot$}
          \State \textbf{return} color $(\xi, c)$
        \EndIf
      \EndFor
    \EndIf
    \State $D^{(\ell)} \gets D^{(\ell)} \cup \{\{x,y\}\}$\label{step:record-unpartialcolored-edge}
    \State Increase reference count for $\{x,y\}$ in $R$
    \State Greedily pick a color class $c \in [C^{(\ell)}]$ not used by any edge in $D^{(\ell)}$ adjacent to $x$ or $y$
    \State $\chi^{(\ell)}_{\{x,y\}} \gets (0,c)$
    \State $M^{(\ell)}_{\{x,y\}} \gets 1$
    \State \textbf{return} color $(0,  c)$
\end{algorithmic}

\caption{Deterministic algorithm for $O(\Delta (\log \Delta)^2)$ edge coloring for multigraph edge arrival streams\label{alg:det-ea-edgecol}}
\begin{algorithmic}[1]
\Statex \textbf{Input}: Stream of edge arrivals $n$-vertex graph $G=(V,E)$
  \Statex Assume $\Delta$ is a power of two
  \Statex
  \Statex \underline{\textbf{Initialize}:}

  \State Let $R \gets \emptyset$ be a reference counted pool of edges. (This will be a set of "recent" edges for each layer in each level, including edges that are either in $D^{(\ell)}$ or have a reference from one of the $F_x^{(\ell,\xi)}$
  \State Each edge $e \in R$ will have, per level $\ell$, one associated counter $M^{(\ell)}_{e} \in [0, 2^\ell]$ and color class $\chi^{(\ell)}_{e} \in \{0,\ldots,\ceil{\log_{3/2}{\Delta^{(\ell)}}}\} \times [C^{(\ell)}]$. When an edge is added to the pool, $M^{(\ell)}_{e} = 0$ for all layers.

  \For{each \emph{level} $\ell$ in $0,\ldots,\log \Delta$}
    \State Define $\Delta^{(\ell)} = \Delta / 2^\ell$
    \State $\mathfrak{K}^{(\ell)} \gets$ \textsc{Initialize}($\ell$,$\Delta^{(\ell)}$) from \Cref{alg:det-ea-inner}
  \EndFor

\Statex 
\Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color}}

  \For{$\ell$ in $0,\ldots,\log \Delta$}\label{step:det-ea-edgecol-outer-loop}
    \If{$\{x,y\}$ is in $R$ and $M^{(\ell)}_{\{x,y\}} > 0$}
      \If{$M^{(\ell)}_{\{x,y\}} = 2^\ell$}
        \State \textbf{continue}\label{step:skip-to-next-level}
      \Else
        \State $M^{(\ell)}_{\{x,y\}} \gets M^{(\ell)}_{\{x,y\}} + 1$
        \State Let $(i,j) \gets \chi^{(\ell)}_{\{x,y\}}$
        \State \textbf{return} color $\left(\ell, i,  (j - 1) 2^\ell + M^{(\ell)}_{\{x,y\}}\right)$
      \EndIf
    \Else
      \State Let $(\xi, c) \gets \mathfrak{K}^{(\ell)}.\textsc{Process}$($\{x,y\}$) for level $\ell$ algorithm
      \State \textbf{return} color $\left(\ell, \xi,  (c - 1) 2^\ell + 1\right)$
    \EndIf
  \EndFor
\end{algorithmic}

