\label{lem:moment-gen-func}
   Let $W$ be a nonnegative integral random variable where, for all $k \in \mathbb{N}$, $\Pr[W \ge k] \le 1/2^k$. Then $\mathbb{E}[W] \le 1$; and furthermore, for all $t$ for which $e^t \in [1,2)$:
   \begin{align*}
        \mathbb{E}[e^{t W}] \le \frac{1}{2 - e^t}
   \end{align*}

\begin{align*}
        \mathbb{E}[e^{t W}] \le \frac{1}{2 - e^t}
   \end{align*}

First,
\begin{align*}
  \mathbb{E}[W] = \sum_{k=0}^{\infty} \Pr[W \ge k] \le \sum_{k=0} 1/2^{k + 1} = 1
\end{align*}
Next,
\begin{align*}
  \mathbb{E}[e^{t W}] &= \sum_{k=0}^{\infty} e^{t k} \Pr[W = k] \le \sum_{k=0}^{\infty} e^{t k} \frac{1}{2^{k+1}} = \frac{1}{2} \sum_{k=0}^{\infty} \left(\frac{e^t}{2}\right)^k = \frac{1}{2}\cdot\frac{1}{1 - \frac{1}{2}e^t} = \frac{1}{2 - e^t}
\end{align*}
The inequality step follows because:

\begin{align*}
   \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k+1}} - \Pr[W = k]\right)
      &= \sum_{k=0}^{\infty} e^{t k} \left((\frac{1}{2^{k}} - \frac{1}{2^{k+1}}) -(\Pr[W \ge k] - \Pr[W \ge k - 1])\right) \\
      &= \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right)
        - \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k + 1}} - \Pr[W \ge k - 1]\right) \\
      &= \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right)
        - \sum_{k=1}^{\infty} e^{t (k - 1)} \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right) \\
      &= \left(\frac{1}{2^{0} - \Pr[W \ge 0]}\right) + \sum_{k=1}^{\infty} (e^t - e^{t (k - 1)}) \left( \frac{1}{2^{k} - \Pr[W \ge k]}\right) \\
      &= 0 + \sum_{k=1}^{\infty} e^{t (k -1)}(e^t - 1) \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right) \ge 0
\end{align*}

\begin{align*}
    \mathbb{E}[W] = \sum_{k=0}^{\infty} \Pr[W \ge k] \le \sum_{k=0} 1/2^{k + 1} = 1
  \end{align*}

\begin{align*}
    \mathbb{E}[e^{t W}] &= \sum_{k=0}^{\infty} e^{t k} \Pr[W = k] \le \sum_{k=0}^{\infty} e^{t k} \frac{1}{2^{k+1}} = \frac{1}{2} \sum_{k=0}^{\infty} \left(\frac{e^t}{2}\right)^k = \frac{1}{2}\cdot\frac{1}{1 - \frac{1}{2}e^t} = \frac{1}{2 - e^t}
  \end{align*}

\label{lem:fast-permutations}
  For any $C$ which is a power of 2, there is an explicit construction of an $(\epsilon,s)$-wise independent
  random permutation, using $r = O(s (\log C)^4 \log \frac{1}{\epsilon})$ bits. Furthermore, we can evaluate $\sigma(i)$ and $\sigma^{-1}(i)$ in $O(s (\log C)^4 \log \frac{1}{\epsilon} \log C)$ time.

Let $k = O(d^3 + d \ln(1/\epsilon))$ be the constant for which $k$ Thorp shuffle steps would permute $[C] = [2^d]$ within total variation distance of $\epsilon$ of the uniform distribution over permutations on $[2^d]$.



The switching network $\mathcal{N}$ corresponding to the $k$ Thorp shuffle steps has depth $k$ and uses exactly $k C / 2$ gates. Assign each gate a unique number in $[kC/2]$. Then given a uniformly random bit vector $x \in \{0,1\}^{k C / 2}$, we evaluate the switching network by having the gate numbered $i$ switch its inputs iff $x_i = 1$. A key property of switching networks is that one can evaluate their action on a single
input by only evaluating one gate per layer -- for this network, only $k$ gates. Reversing the order in which the layers are applied will produce the inverse of the original permutation. Thus, one can evaluate
$\mathcal{N}(i)$ by reading only $k$ entries of $x$, and similarly for and $\mathcal{N}^{-1}{i}$.

Now, say the bits of $x$ are the output of a hash function drawn from a $k s$-wise independent hash family. (For example, using a family of \cite{WegmanC81}, let $h = \ceil{\log_2{k C / 2}}$, take the family of random polynomials of degree $k s - 1$ inside $\mathbb{F}_{2^{h}}$, and output the least bit of the output. The polynomial coefficients can be encoded using $k s h = O(k s \log(C))$ bits, and the polynomials evaluated at any point in $O(k s h^2 ) = O(k s (\log C)^2 )$ time.)

If $\pi$ is a uniformly random permutation on $[C]$, then for all lists of distinct $h_1,\ldots,h_s$, and all lists of distinct $j_1,\ldots,j_s$, we have
\begin{align*}
  \Pr[\bigwedge_{i\in[s]} \pi(h_i) = j_i] = \frac{1}{\prod_{i \in [s]} (C - i + 1)}
\end{align*}

Now, let $f : \{0,1\}^{k C/2} \times [C] \mapsto [C]^k$ be the function which maps the gate-controlling vector $x \in \{0,1\}^{k C / 2}$ and an input $a \in [C]$ to the path $b_1,\ldots,b_k$ that $a$ takes through the switching network $\mathcal{N}$ if its gates are configured according to $x$. The last node of this path, $f(x, a)_k$ is the output of $\mathcal{N}$ given $x$ and $a$. Each path $P = (a,b_1,\ldots,b_k)$ through the switching network corresponds to a restriction $R_P \in \{0,1,\star\}^{k C / 2}$ which has value $\star$ on gates not touched by the path, and for each gate traversed by the path assigns either $0$ or $1$ depending on whether a straight or switched configuration of the gate is compatible with $P$. Since all paths through the network have length $k$, $R_P$ only sets $k$ coordinates. Now, for each pair $(a,b) \in [C]^2$, let 
\begin{align*}
  \mathcal{F}_{a,b} = \{R_P : P = (a,b_1,\ldots,b_{k-1},b) \text{ is a possible path}\}
\end{align*}

Then, for lists $(h_1,\ldots,h_s)$, $(j_1,\ldots,j_s)$, define 
\begin{align*}
  \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s} = \{ R \in \{0,1,\star\}^{k C / 2} : \forall i \in [k], \exists T \in \mathcal{F}_{h_i,j_i} \text{where $R$ is a minimal refinement of $T$}  \}\,,
\end{align*}
i.e., the set of minimal restrictions for vectors in $\{0,1\}^{k C / 2}$ which
completely determine the paths through the switching network of inputs $(h_1,\ldots,h_s)$. 

Now, let $Y \in \{0,1\}^{k C / 2}$ be $k s$-wise independent, and $X \in \{0,1\}^{k C / 2}$ be fully independent. We have:
\begin{align*}
  \Pr[\bigwedge_{i\in[s]} f(Y, h_i)_k = j_i] &= \sum_{R \in \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s}} \Pr[Y \text{ compatible with $R$}] \\
  &= \sum_{R \in \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s}} \Pr[X \text{ compatible with $R$}] \\
  &= \Pr[\bigwedge_{i\in[s]} f(X, h_i)_k = j_i]
\end{align*}
where the second inequality follows because each restriction $R \in \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s}$ only constrains $s k / 2$ coordinates
corresponding to the gates on the paths in the switching network from $h_1,\ldots,h_s$ to $j_1,\ldots,j_s$ that it fixes.

Thus,
\begin{align*}
    &\frac{1}{2} \sum_{\text{distinct $b_1,\ldots,b_k$ in $[C]$,}} \left| \Pr\left[\bigwedge_{i \in [s]} \{ f(X, h_i)_k = j_i \} \right] - \frac{1}{\prod_{i \in [s]} (C - i + 1)} \right| = \\
    &\frac{1}{2} \sum_{\text{distinct $b_1,\ldots,b_k$ in $[C]$,}} \left| \Pr\left[\bigwedge_{i \in [s]} \{ f(Y, h_i)_k = j_i \} \right] - \frac{1}{\prod_{i \in [s]} (C - i + 1)} \right| \le \epsilon
\end{align*}
which proves that the switching network evaluated on $X$ produces outputs that are $(\epsilon,s)$-wise independent.

